const ALT_DAYS = { en: '3 times a week', es: '3 veces por semana' }
const reps = (n: number) => ({ en: `${n}`, es: `${n}` })
const repsEach = (n: number) => ({ en: `${n} each side`, es: `${n} por lado` })
const hold = (s: number) => ({ en: `${s} s hold`, es: `${s} s` })
const holdEach = (s: number) => ({ en: `${s} s each side`, es: `${s} s por lado` })

