export function exerciseCatalogItem(slug: string | null | undefined): CatalogExercise | null {
  if (!slug) return null
  return EXERCISE_CATALOG.find((e) => e.slug === slug) ?? null
}

/** Where a catalogue exercise's video and poster are served, relative to the web app. */
export function exerciseCatalogMediaPaths(slug: string) {
  return { video: `/exercise-catalog/${slug}.mp4`, poster: `/exercise-catalog/${slug}.jpg` }
}
